CREATE TABLE IF NOT EXISTS pejlo_snooze(identifier TEXT NOT NULL,uid TEXT NOT NULL,until_ms INTEGER NOT NULL,PRIMARY KEY(identifier,uid));
CREATE TABLE IF NOT EXISTS pejlo_runs(id TEXT PRIMARY KEY,started_at INTEGER NOT NULL,finished_at INTEGER,status TEXT NOT NULL,checked INTEGER NOT NULL DEFAULT 0,errors INTEGER NOT NULL DEFAULT 0,upstream_requests INTEGER NOT NULL DEFAULT 0,upstream_errors INTEGER NOT NULL DEFAULT 0);
